-- v049b lot 1/4 — présentations 1 à 200 de la LNME Mali 2024 (table d'import uniquement)
-- v049b — Catalogue national : import des 797 présentations de la LNME Mali 2024
--
-- Source : LNME Mali 2024 (annexe de l'arrêté n° 2024-4004/MSDS-SG du 28/10/2024), liste niveau hôpital.
-- 830 lignes transcrites, 33 doublons exacts écartés (même DCI, forme et dosage
-- répétés d'un chapitre à l'autre : la présentation garde toutes ses familles),
-- 169 DCI corrigées (orthographe, césures, marque à la place de la DCI).
-- Une présentation déjà présente au catalogue (même DCI, forme et dosage) est
-- enrichie, jamais dupliquée. Le classement réglementaire est le classement
-- prudent SantéProxi, à valider par un pharmacien.
-- Retour arrière : voir import_catalogue_2026 (colonne action et catalog_id).

create or replace function public.catalog_dosage_key(t text)
returns text language sql immutable parallel safe set search_path to 'public', 'extensions' as $f$
  select regexp_replace(replace(public.normalize_text(coalesce(t, '')), ',', '.'), '[^a-z0-9.%/+]', '', 'g')
$f$;

insert into public.import_catalogue_2026
  (dci, forme, dosage, family, families, subfamily, lnme_ref, regulation, tier, cold_chain, source, note)
select v.dci, v.forme, v.dosage, v.family,
       array[v.family] || coalesce(string_to_array(v.extra, ','), '{}'),
       v.sub, 'LNME Mali 2024, chapitre ' || v.ch, v.reg, v.tier, v.cold, 'LNME Mali 2024 (annexe de l''arrêté n° 2024-4004/MSDS-SG du 28/10/2024), liste niveau hôpital', v.note
